column8:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "name": "educ_search",
  "description": "少儿媒资组合式搜索工具(educ_search)。当用户表达了搜索、查找、推荐少儿内容的意图时触发，包括按标题(title)、媒资类型(content_type)、蛛网标签二级分类(children_second_genre)/三级分类(children_third_genre)、少儿培养目标(training_objectives)、角色(role)、少儿八大智能(multiple_intelligences)、国家(country)、出品公司(company)、语言(language)、性别(gender)、节日(festival)、奖项(prize)/子奖项(sub_prize)、音效(features)、年级(grade)等维度筛选，以及按免付费状态(is_fee)过滤和发布时间范围(release_year, 格式yyyyMMdd)筛选的场景。支持16个精确匹配维度、1个状态维度(is_fee 0|1)和1个范围维度(release_year 发布时间区间)。同一维度多值时通过values数组+operator字段指定逻辑(or任一匹配/and全部匹配，默认or)。不同维度间通过BoolNode组合：and(与)、or(或)、not(非)，支持任意嵌套。",
  "type": "object",
  "properties": {
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND/OR/NOT 组成的复合节点。"
    },
    "sort": {
      "type": "object",
      "description": "排序规则(三种排序键的候选值固定为 asc/desc)，可选 rate(评分)、hot(热度)、new(发布时间) 中的一种或多种组合。三者差异：rate 按 用户/专家评分高低排序，hot 按综合热度(播放量、搜索量等) 排序，new 按发布时间新旧排序。每个排序键的 order 取 asc(正序) 或 desc(倒序)。不传 sort 表示不涉及排序。",
      "properties": {
        "rate": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "hot": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "new": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        }
      },
      "additionalProperties": false,
      "minProperties": 1
    }
  },
  "required": ["query"],
  "additionalProperties": false,

  "definitions": {

    "QueryNode": {
      "description": "查询节点，支持两种形态：1) 布尔复合节点(AND/OR/NOT)；2) 叶子条件节点(单个字段的匹配条件)。",
      "oneOf": [
        { "$ref": "#/definitions/BoolNode" },
        { "$ref": "#/definitions/LeafNode" }
      ]
    },

    "BoolNode": {
      "description": "布尔逻辑组合节点，支持 AND(与)、OR(或)、NOT(非) 三种组合方式。可嵌套组合。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": ["and"],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "OR逻辑：子节点条件中至少满足一个。"
            }
          },
          "required": ["or"],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：对子节点条件取反。"
            }
          },
          "required": ["not"],
          "additionalProperties": false
        }
      ]
    },

    "LeafNode": {
      "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。field 指定维度，value 指定匹配值。",
      "type": "object",
      "oneOf": [
        { "$ref": "#/definitions/ExactFieldCondition" },
        { "$ref": "#/definitions/StatusFieldCondition" },
        { "$ref": "#/definitions/RangeFieldCondition" }
      ]
    },

    "ExactFieldCondition": {
      "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，通过 operator 字段控制维度内的逻辑关系：\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "搜索维度字段名（共16个精确匹配维度）。候选类型分三类：固定候选(取值有限可枚举，模型应在候选内取值或归一化)、半固定候选(常见取值有限但可扩展)、开放型(取值不可枚举，按语义自由填入)。部分字段间存在语义边界，需按各 const 描述中的差异化说明选择正确字段。",
          "oneOf": [
            { "const": "title", "description": "媒资作品标题(开放型)。搜索具体的作品名称时使用。与 role(人物角色) 不同——title 是作品本身的名字(如西游记)，role 是作品中的人物(如孙悟空)。典型取值：动画片名(小猪佩奇、汪汪队)、电影名(战狼、流浪地球)、电视剧名(甄嬛传)、游戏名(斗罗大陆、王者荣耀)、儿歌歌曲名(红蜻蜓、葫芦娃)、儿歌集锦名(儿歌多多)、儿童故事名(葫芦娃、三毛)、玩具名(陀螺、溜溜球)、玩具视频名(芭比玩具)、儿童视频名(挖掘机)、漫画名、手工类型、棋类名称、ar百科媒资(摩托车、北极熊)、儿童课程类型(国学经典、启蒙教育)、书本册数(上册、下册)、儿童舞蹈类型-聚好看(萌动)、少儿视频弱标签(老鼠爱大米、起风了)等" },
            { "const": "content_type", "description": "媒资表现形式(固定候选)。仅在用户明确区分媒资形态时使用，候选值：动画、卡通、动画片、动画剧、动画剧集。与 children_third_genre(主题标签) 不同——content_type 描述\"是什么形态的媒资\"，children_third_genre 描述\"讲什么主题的内容\"" },
            { "const": "children_second_genre", "description": "蛛网标签-二级分类(固定候选)。少儿内容蛛网分类体系下的较粗粒度大类标签。与 children_third_genre(三级分类) 是上下位关系——second_genre 是大类，third_genre 是其下的细分标签，候选值：动漫、电影、绘本、儿歌、玩具、真人、音频、宠物、早教、科普、英语、国学、数学、才艺、故事、家长课堂、经典、国学启蒙、数学启蒙、动画电影、漫画、音乐" },
            { "const": "children_third_genre", "description": "蛛网标签-三级分类(固定候选)。少儿内容蛛网分类体系下的较细粒度标签，是 children_second_genre(二级分类) 的下位细分。候选值：搞笑、工程车、红色旋律、交通工具、竞技、机甲、科幻、历史、礼仪品德、励志、美食、魔幻、情绪管理、亲子、奇幻、热血、生活日常、推理、温馨治愈、性格培养、习惯养成、益智动画、友情、动作、感动、冒险、校园、分级阅读、两性教育、入园适应、杂志期刊、综合绘本、益智儿歌、综合儿歌、安静书、巴克球、开箱、史莱姆、食玩、玩具情景剧、玩玩具、儿童真人秀、少儿综艺、真人益智、安全知识、百科综合、动物百科、工程技术、海洋百科、海洋动物、家用电器、节气、节日、科学原理、恐龙、昆虫、鸟类、人体奥秘、人文地理、生活知识、身体健康、细菌病毒、宇宙、植物百科、职业知识、自然现象、词汇、情景教学、小语种、幼小衔接、字母、自然拼读、成语典故、国学启蒙、古诗词、汉字、经典名著、拼音、财商、基础运算、逻辑思维、数学知识、数字、形状、儿童才艺、绘画、口才、乐器、魔术、棋艺、手工、书法、体操、舞蹈、名人故事、神话故事、睡前故事、童话故事、益智故事、幽默、寓言故事、综合故事、分龄早教、家庭教育、亲子游戏、育婴育儿、安全教育、古诗、益智、跳舞、跳舞吧、风舞、舞蹈课、舞、歌舞、跳跳舞、舞蹈健身、舞蹈教程、红色、航天、拼音汉字、拼音汉字、小红军、探案、探险、悬疑、破案、诗、唐诗、文言文、背古诗、宋词、词、诗歌、诗词、诗歌大全、古诗全集、南北朝民歌、诗文、古文、央视" },
            { "const": "training_objectives", "description": "少儿培养目标(固定候选)。按教育目标筛选内容时使用。候选值：宝宝学数字、识字、强健体魄、勇敢、行为认知、乐于助人、生活习惯、认识形状、认识颜色、英语启蒙、认识数字、认识海洋动物、认识动物、认识恐龙、情绪管理、情商培养、手工制作、消防安全、安全教育、拼音、认识时间、安全课教育、诚实守信、兴趣培养、亲子关系、安全教育课程、安全课堂、安全课、安全小知识、爱护动物、安全小课堂、安全教育课、安全课教育课程、培养好性格、认识宇宙、团队协作、财商教育、心理健康、记忆力、朋友交往、安全意识、音乐启蒙、认字、字母学习、学习成语典故、学习古诗词、掌握自然拼读、培养语感、词汇学习、学习经典古文、认识拼音、语言表达能力、了解传统文化、听说能力、学习经典名著、认识日常汉字、阅读能力、了解国外文化、认识食物、了解科学知识、感知世界、认识昆虫、认识各种职业、了解生命科学、了解历史文化、认识球类、认识电器、了解地理知识、观察能力、认识历史、认识气候、日常生活认知、探索能力、认识植物、认识微生物、认识海底世界、了解动物习性、认识蔬菜、认识交通工具、节日认知、环保意识、数学知识、基础运算能力、逻辑思维能力、饮食习惯、情绪情感、讲卫生习惯、自理能力、讲文明讲礼貌、性别教育、爱国精神、培养责任心、积极乐观、树立自信心、独立意识、培养安全感、解决问题能力、社会适应能力、乐于分享、拥有共情能力、人宠关系、正义感、培养幽默感、认识乐器乐理、培养节奏韵律感。与 multiple_intelligences(八大智能) 不同——training_objectives 偏教学目标导向(如培养专注力、启蒙认知)，multiple_intelligences 偏智能维度分类(如语言智能、逻辑数学智能)" },
            { "const": "role", "description": "角色(开放型)。作品中的具体人物角色。与 title(作品名称) 不同——role 是作品中的人物(如孙悟空、路飞)，title 是作品本身的名字(如西游记、海贼王)。适用场景如\"找有路飞出场的动画\"" },
            { "const": "multiple_intelligences", "description": "少儿八大智能(固定候选)。按多元智能理论筛选内容。候选值：人际交往、空间想象、品格习惯、识物认知、数字推理、音乐节奏、肢体运动、语言沟通、学说话。与 training_objectives(培养目标) 不同——multiple_intelligences 是智能维度分类(语言智能、逻辑数学智能、空间智能等)，training_objectives 是教学目标导向" },
            { "const": "country", "description": "国家/地区(开放型)。按地理维度筛选内容时使用。与 language(语言) 不同——country 是地理概念(中国、山东、卢森堡)，language 是语言本身(中文、英语)；当一词多义(如\"中华\")时按用户意图归类。典型取值：外国国家名(卢森堡、苏格兰)、中国国家(中国)、国内省份(山东、陕西)、国内区域名(中华、香港)、国外区域名(中东、欧亚)、地区(中东)等" },
            { "const": "company", "description": "出品公司(开放型)。制作或发行该媒资的公司主体。适用场景如\"找时光传媒出品的动画\"。典型取值：影视出品公司(时光传媒)等" },
            { "const": "language", "description": "语言(固定候选)。影片的主要对白语言、语种或语言版本。与 country(地理) 不同——language 描述作品使用的语言或制作风格的地域版本，country 是地理归属。候选值：英文版、阿拉伯文、阿拉伯语、白俄罗斯语、德文、德语、俄文、俄语、方言、法文、法语、国语、国语版、汉语、库尔德语、孟加拉语、葡萄牙语、普通话、其他语言、日本语、日文、日语、日语版、瑞士德语、泰国语、泰卢固语、泰文、泰语、无对白、西班牙语、西文、英文、英文版、英语、印地语、印度尼西亚语、印度语、印尼语、意大利语、粤语、粤语版、朝鲜语、中国话、中文、中文版、方言版" },
            { "const": "gender", "description": "受众人群性别(固定候选)。按目标受众性别筛选内容时使用。候选值：妇女、美女、男、男版、男宝、男宝宝、男歌手、男声、男生、男声版、男生版、男士、男性、男子、女、女版、女宝、女宝宝、女歌手、女声、女生、女声版、女生版、女士、女式、女性、女子、小男生、小女生、小男孩、女孩、女孩儿、女孩子、小女孩、男孩、男孩儿、男孩子。如果不提及或者男女都可，则置空。适用场景如\"适合男生看的电影\"、\"女生喜欢的动画片\"" },
            { "const": "festival", "description": "节日(固定候选)。按节日筛选内容时使用。后悬置：春节、元宵节、清明节、端午节、七夕节、中秋节、重阳节、腊八节、元旦、国际妇女节、植树节、劳动节、儿童节、建党节、建军节、教师节、国庆节、情人节、愚人节、复活节、母亲节、父亲节、万圣节、感恩节、圣诞节。与 release_year(具体日期范围) 不同——festival 是节日名(除夕、端午)，release_year 是 yyyyMMdd 格式的精确日期区间。" },
            { "const": "prize", "description": "奖项(固定候选)。整体奖项名称。候选值：奥斯卡、奥斯卡奖、奥斯卡金像奖、百花奖、柏林电影节、柏林电影节金熊奖、柏林国际电影节、柏林金熊奖、白玉兰颁奖、白玉兰奖、大众电影百花奖、法国嘎纳电影节、飞天奖、华表奖、华鼎奖、华语电影传媒大奖、戛纳、戛纳电影节、戛纳电影节金棕榈奖、戛纳国际电影节、戛纳金棕榈奖、金鸡百花奖、金鸡百花节、金鸡奖、金鸡节、金马奖、金狮奖、金像奖、金熊奖、金鹰奖、金棕榈、金棕榈奖、上海电视节白玉兰奖、台北金马奖、台湾电影金马奖、威尼斯电影节、威尼斯电影节金狮奖、威尼斯金狮奖、香港电影金像奖、熊猫奖、中国电视金鹰奖、中国电视剧飞天奖、中国电影华表奖、中国电影金鸡奖、凯迪克大奖、中国音乐金钟奖、北京大学生电影节、国际安徒生奖、音乐风云榜、金鹰节。与 sub_prize(子奖项) 是上下位关系——prize 是奖项整体(如金鸡奖、金马奖)，sub_prize 是该奖项下的具体子项(如最佳男配角、最佳女主角)。当用户只说\"金鸡奖\"用 prize，说\"金鸡奖最佳男主角\"则 prize+sub_prize 组合使用" },
            { "const": "sub_prize", "description": "子奖项(开放型)。奖项下的具体子项，是 prize(奖项整体) 的下位细分。与 prize 配合使用以精确指向某一具体奖项子项。典型取值：最佳男配角、最佳女主角、最佳导演等。适用场景如\"找获得最佳男主角的影片\"" },
            { "const": "features", "description": "音效(固定候选)。技术性音效标识。候选值：杜比、杜比音效。适用场景如\"找支持杜比音效的内容\"" },
            { "const": "grade", "description": "年级。按目标受众的学段或筛选内容时使用。候选值：幼儿园阶段(小班、中班、大班)、小学年级(一年级~六年级)等" }
          ]
        },
        "value": { "type": "string", "description": "单值精确匹配" },
        "values": {
          "type": "array",
          "items": { "type": "string" },
          "minItems": 1,
          "description": "多值匹配，逻辑关系由 operator 字段决定"
        },
        "operator": {
          "type": "string",
          "enum": ["and", "or"],
          "default": "or",
          "description": "维度内多值逻辑关系。\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。仅在使用 values 时生效。"
        }
      },
      "required": ["field"],
      "oneOf": [
        { "required": ["value"] },
        { "required": ["values"] }
      ],
      "additionalProperties": false
    },

    "StatusFieldCondition": {
      "description": "状态标识条件(固定候选 0/1)。用于枚举状态字段，值为 0 或 1 的整数。is_fee: 0=免费, 1=付费。不传表示不涉及该条件。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "状态字段名",
          "oneOf": [
            { "const": "is_fee", "description": "免付费标识。0=免费，1=付费。适用场景如\"找免费内容\"、\"找VIP付费内容\"。与 ExactFieldCondition 中的其他维度不同——is_fee 是布尔型状态过滤，不参与主题/属性匹配" }
          ]
        },
        "value": {
          "type": "integer",
          "enum": [0, 1],
          "description": "状态值，0 或 1。is_fee: 0=免费(对应自然语言\"免费/不要钱\")，1=付费(对应自然语言\"付费/VIP\")。自然语言中的\"打折/五折/半价\"等费用相关词需归一化为 0 或 1 后传入。"
        }
      },
      "required": ["field", "value"],
      "additionalProperties": false
    },

    "RangeFieldCondition": {
      "description": "范围匹配条件。支持 age_range(年龄范围) release_year(发布时间范围)含边界。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "范围搜索维度字段名",
          "oneOf": [
            { "const": "age_range", "description": "年龄范围筛选，三种模式：1. \"3 TO 6\"年龄区间；2. \"* TO 6\"不超过6岁；3. \"6 TO *\"不小于6岁" },
            { "const": "release_year", "description": "发布时间范围。from/to 均为 yyyyMMdd 格式字符串，含边界" }
          ]
        },
        "from": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "发布日期下限(含)，age_range为整数，release_year格式 yyyyMMdd，如 20200101。自然语言归一化示例：\"2023年/2023\"→from:20230101；\"去年/上一年/明年\"→from:对应年份1月1日；\"80年代\"→from:19800101；\"近一年/近5年\"等时间段→from:对应起始日期；\"本周一/上周一\"等星期表达→from:对应日期。"
        },
        "to": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "发布日期上限(含)，age_range为整数，release_year格式 yyyyMMdd，如 20231231。归一化示例：\"2023年\"→to:20231231；\"80年代\"→to:19891231；\"近一年/近5年\"→to:当天日期；\"本周一/上周一\"→to:对应日期。"
        }
      },
      "required": ["field", "from", "to"],
      "additionalProperties": false
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "name": "educ_search",
  "description": "少儿媒资组合式搜索工具(educ_search)。当用户表达了搜索、查找、推荐少儿内容的意图时触发，包括按标题(title)、媒资类型(content_type)、蛛网标签二级分类(children_second_genre)/三级分类(children_third_genre)、角色(role)、出品公司(company)、语言(language)、性别(gender)、节日(festival)等维度筛选，以及按免付费状态(is_fee)过滤筛选的场景。支持9个精确匹配维度、1个状态维度(is_fee 0|1)。同一维度多值时通过values数组+operator字段指定逻辑(or任一匹配/and全部匹配，默认or)。不同维度间通过BoolNode组合：and(与)、or(或)、not(非)，支持任意嵌套。",
  "type": "object",
  "properties": {
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND/OR/NOT 组成的复合节点。"
    },
    "sort": {
      "type": "object",
      "description": "排序规则(三种排序键的候选值固定为 asc/desc)，可选 rate(评分)、hot(热度)、new(发布时间) 中的一种或多种组合。三者差异：rate 按 用户/专家评分高低排序，hot 按综合热度(播放量、搜索量等) 排序，new 按发布时间新旧排序。每个排序键的 order 取 asc(正序) 或 desc(倒序)。不传 sort 表示不涉及排序。",
      "properties": {
        "rate": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "hot": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "new": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        }
      },
      "additionalProperties": false,
      "minProperties": 1
    }
  },
  "required": ["query"],
  "additionalProperties": false,

  "definitions": {

    "QueryNode": {
      "description": "查询节点，支持两种形态：1) 布尔复合节点(AND/OR/NOT)；2) 叶子条件节点(单个字段的匹配条件)。",
      "oneOf": [
        { "$ref": "#/definitions/BoolNode" },
        { "$ref": "#/definitions/LeafNode" }
      ]
    },

    "BoolNode": {
      "description": "布尔逻辑组合节点，支持 AND(与)、OR(或)、NOT(非) 三种组合方式。可嵌套组合。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": ["and"],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "OR逻辑：子节点条件中至少满足一个。"
            }
          },
          "required": ["or"],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：对子节点条件取反。"
            }
          },
          "required": ["not"],
          "additionalProperties": false
        }
      ]
    },

    "LeafNode": {
      "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。field 指定维度，value 指定匹配值。",
      "type": "object",
      "oneOf": [
        { "$ref": "#/definitions/ExactFieldCondition" },
        { "$ref": "#/definitions/StatusFieldCondition" },
        { "$ref": "#/definitions/RangeFieldCondition" }
      ]
    },

    "ExactFieldCondition": {
      "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，通过 operator 字段控制维度内的逻辑关系：\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "搜索维度字段名（共16个精确匹配维度）。候选类型分三类：固定候选(取值有限可枚举，模型应在候选内取值或归一化)、半固定候选(常见取值有限但可扩展)、开放型(取值不可枚举，按语义自由填入)。部分字段间存在语义边界，需按各 const 描述中的差异化说明选择正确字段。",
          "oneOf": [
            { "const": "title", "description": "媒资作品标题(开放型)。搜索具体的作品名称时使用。与 role(人物角色) 不同——title 是作品本身的名字(如西游记)，role 是作品中的人物(如孙悟空)。典型取值：动画片名(小猪佩奇、汪汪队)、电影名(战狼、流浪地球)、电视剧名(甄嬛传)、游戏名(斗罗大陆、王者荣耀)、儿歌歌曲名(红蜻蜓、葫芦娃)、儿歌集锦名(儿歌多多)、儿童故事名(葫芦娃、三毛)、玩具名(陀螺、溜溜球)、玩具视频名(芭比玩具)、儿童视频名(挖掘机)、漫画名、手工类型、棋类名称、ar百科媒资(摩托车、北极熊)、儿童课程类型(国学经典、启蒙教育)、书本册数(上册、下册)、儿童舞蹈类型-聚好看(萌动)、少儿视频弱标签(老鼠爱大米、起风了)等" },
            { "const": "content_type", "description": "媒资表现形式(固定候选)。仅在用户明确区分媒资形态时使用，候选值：动画、卡通、动画片、动画剧、动画剧集。与 children_third_genre(主题标签) 不同——content_type 描述\"是什么形态的媒资\"，children_third_genre 描述\"讲什么主题的内容\"" },
            { "const": "children_second_genre", "description": "蛛网标签-二级分类(固定候选)。少儿内容蛛网分类体系下的较粗粒度大类标签。与 children_third_genre(三级分类) 是上下位关系——second_genre 是大类，third_genre 是其下的细分标签，候选值：动漫、电影、绘本、儿歌、玩具、真人、音频、宠物、早教、科普、英语、国学、数学、才艺、故事、家长课堂、经典、国学启蒙、数学启蒙、动画电影、漫画、音乐" },
            { "const": "children_third_genre", "description": "蛛网标签-三级分类(固定候选)。少儿内容蛛网分类体系下的较细粒度标签，是 children_second_genre(二级分类) 的下位细分。候选值：搞笑、工程车、红色旋律、交通工具、竞技、机甲、科幻、历史、礼仪品德、励志、美食、魔幻、情绪管理、亲子、奇幻、热血、生活日常、推理、温馨治愈、性格培养、习惯养成、益智动画、友情、动作、感动、冒险、校园、分级阅读、两性教育、入园适应、杂志期刊、综合绘本、益智儿歌、综合儿歌、安静书、巴克球、开箱、史莱姆、食玩、玩具情景剧、玩玩具、儿童真人秀、少儿综艺、真人益智、安全知识、百科综合、动物百科、工程技术、海洋百科、海洋动物、家用电器、节气、节日、科学原理、恐龙、昆虫、鸟类、人体奥秘、人文地理、生活知识、身体健康、细菌病毒、宇宙、植物百科、职业知识、自然现象、词汇、情景教学、小语种、幼小衔接、字母、自然拼读、成语典故、国学启蒙、古诗词、汉字、经典名著、拼音、财商、基础运算、逻辑思维、数学知识、数字、形状、儿童才艺、绘画、口才、乐器、魔术、棋艺、手工、书法、体操、舞蹈、名人故事、神话故事、睡前故事、童话故事、益智故事、幽默、寓言故事、综合故事、分龄早教、家庭教育、亲子游戏、育婴育儿、安全教育、古诗、益智、跳舞、跳舞吧、风舞、舞蹈课、舞、歌舞、跳跳舞、舞蹈健身、舞蹈教程、红色、航天、拼音汉字、拼音汉字、小红军、探案、探险、悬疑、破案、诗、唐诗、文言文、背古诗、宋词、词、诗歌、诗词、诗歌大全、古诗全集、南北朝民歌、诗文、古文、央视" },
            { "const": "role", "description": "角色(开放型)。作品中的具体人物角色。与 title(作品名称) 不同——role 是作品中的人物(如孙悟空、路飞)，title 是作品本身的名字(如西游记、海贼王)。适用场景如\"找有路飞出场的动画\"" },
            { "const": "company", "description": "出品公司(开放型)。制作或发行该媒资的公司主体。适用场景如\"找时光传媒出品的动画\"。典型取值：影视出品公司(时光传媒)等" },
            { "const": "language", "description": "语言(半固定候选)。影片的主要对白语言、语种或语言版本。与 country(地理) 不同——language 描述作品使用的语言或制作风格的地域版本，country 是地理归属。常见取值：英文版、阿拉伯文、阿拉伯语、白俄罗斯语、德文、德语、俄文、俄语、方言、法文、法语、国语、国语版、汉语、库尔德语、孟加拉语、葡萄牙语、普通话、其他语言、日本语、日文、日语、日语版、瑞士德语、泰国语、泰卢固语、泰文、泰语、无对白、西班牙语、西文、英文、英文版、英语、印地语、印度尼西亚语、印度语、印尼语、意大利语、粤语、粤语版、朝鲜语、中国话、中文、中文版、方言版" },
            { "const": "gender", "description": "受众人群性别(固定候选)。按目标受众性别筛选内容时使用。候选值：妇女、美女、男、男版、男宝、男宝宝、男歌手、男声、男生、男声版、男生版、男士、男性、男子、女、女版、女宝、女宝宝、女歌手、女声、女生、女声版、女生版、女士、女式、女性、女子、小男生、小女生、小男孩、女孩、女孩儿、女孩子、小女孩、男孩、男孩儿、男孩子。如果不提及或者男女都可，则置空。适用场景如\"适合男生看的电影\"、\"女生喜欢的动画片\"" },
            { "const": "festival", "description": "节日(开放型)。按节日筛选内容时使用。与 release_year(具体日期范围) 不同——festival 是节日名(除夕、端午)，release_year 是 yyyyMMdd 格式的精确日期区间。典型取值：时间-节日(除夕、端午)等" }
          ]
        },
        "value": { "type": "string", "description": "单值精确匹配" },
        "values": {
          "type": "array",
          "items": { "type": "string" },
          "minItems": 1,
          "description": "多值匹配，逻辑关系由 operator 字段决定"
        },
        "operator": {
          "type": "string",
          "enum": ["and", "or"],
          "default": "or",
          "description": "维度内多值逻辑关系。\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。仅在使用 values 时生效。"
        }
      },
      "required": ["field"],
      "oneOf": [
        { "required": ["value"] },
        { "required": ["values"] }
      ],
      "additionalProperties": false
    },

    "StatusFieldCondition": {
      "description": "状态标识条件(固定候选 0/1)。用于枚举状态字段，值为 0 或 1 的整数。is_fee: 0=免费, 1=付费。不传表示不涉及该条件。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "状态字段名",
          "oneOf": [
            { "const": "is_fee", "description": "免付费标识。0=免费，1=付费。适用场景如\"找免费内容\"、\"找VIP付费内容\"。与 ExactFieldCondition 中的其他维度不同——is_fee 是布尔型状态过滤，不参与主题/属性匹配" }
          ]
        },
        "value": {
          "type": "integer",
          "enum": [0, 1],
          "description": "状态值，0 或 1。is_fee: 0=免费(对应自然语言\"免费/不要钱\")，1=付费(对应自然语言\"付费/VIP\")。自然语言中的\"打折/五折/半价\"等费用相关词需归一化为 0 或 1 后传入。"
        }
      },
      "required": ["field", "value"],
      "additionalProperties": false
    },

    "RangeFieldCondition": {
      "description": "范围匹配条件。支持 age_range(年龄范围) 含边界。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "范围搜索维度字段名",
          "oneOf": [
            { "const": "age_range", "description": "年龄范围筛选，三种模式：1. \"3 TO 6\"年龄区间；2. \"* TO 6\"不超过6岁；3. \"6 TO *\"不小于6岁" }
          ]
        },
        "from": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "范围起始值(含)。age_range 为整数。"
        },
        "to": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "范围结束值(含)。age_range 为整数"
        }
      },
      "required": ["field", "from", "to"],
      "additionalProperties": false
    }
  }
}

{
    "name": "educ_slow_search_data_search",
    "title": "教育_内容搜索_慢链路_数据搜索",
    "url": "https://api.example.com/educ/search",
    "method": "POST",
    "description": "功能：教育内容非明确的复杂语义搜索。用于处理用户以模糊、描述性、问答等方式表达教育/少儿内容查找意图的场景，包括按受众描述、组合条件、问答式查询等，系统将自然语言解析为结构化筛选参数后进行检索。\n适用场景：1. 受众描述类查询，如\"适合3到6岁男孩的英语启蒙动画\"、\"给学龄前小朋友看的免费儿歌\"；2. 问答式查询，如\"有没有适合女童的国产动画\"（解析为gender+country+tag条件）、\"有没有免费的英语启蒙内容\"（解析为is_fee+language+tag条件）；3. 复杂组合描述，如\"非国产的、免费的、适合6岁以上孩子的英语教学内容\"、\"不是收费的、日本出的、适合女童的动漫\"；4. 语言/产地相关的模糊查找。\n不适用场景：简单明确的查询不要使用该工具，如\"播放小猪佩奇\"、\"打开英语启蒙频道\"、\"看儿歌多多\"等直接指定了明确内容名称或固定分类的请求，应使用明确的检索工具。\n异常：无法解析用户意图时results返回空对象且status_code为200；参数格式错误时status_code为500。\n结果使用：results中各字段反映系统从用户自然语言中解析出的结构化筛选条件，用于确认解析意图并展示匹配内容。",
    "parameters": {
        "type": "object",
        "properties": {
            "tag": {
                "type": "string",
                "description": "二级分类筛选",
                "enum": [
                    "才艺",
                    "宠物",
                    "动画",
                    "动画电影",
                    "儿歌",
                    "故事",
                    "国学",
                    "绘本",
                    "家长课堂",
                    "经典",
                    "科普",
                    "少儿动漫",
                    "数学",
                    "玩具",
                    "音频",
                    "英语",
                    "早教",
                    "真人"
                ]
            },
            "age_range": {
                "type": "string",
                "description": "年龄范围筛选，三种模式：1. \"3 TO 6\"年龄区间；2. \"* TO 6\"不超过6岁；3. \"6 TO *\"不小于6岁"
            },
            "gender": {
                "type": "string",
                "description": "性别筛选",
                "enum": [
                    "男",
                    "女"
                ]
            },
            "country": {
                "type": "string",
                "description": "内容出品国家/地区名，如\"中国\"、\"美国\"、\"日本\"、\"英国\"、\"韩国\"等"
            },
            "language": {
                "type": "string",
                "description": "内容语种，如\"中文\"、\"英语\"、\"日语\"、\"韩语\"、\"法语\"等"
            },
            "is_fee": {
                "type": "string",
                "description": "是否收费筛选",
                "enum": [
                    "0",
                    "1"
                ]
            }
        },
        "required": [

        ]
    },
    "output": {
        "type": "object",
        "properties": {
            "results": {
                "type": "object",
                "description": "搜索结果，包含解析后的筛选条件回显",
                "properties": {
                    "tag": {
                        "type": "string",
                        "description": "二级分类"
                    },
                    "age_range": {
                        "type": "string",
                        "description": "年龄范围条件。三种模式：1. \"number1 TO number2\"；2. \"* TO number2\"；3. \"number1 TO *\""
                    },
                    "gender": {
                        "type": "string",
                        "description": "性别，\"男\"或\"女\""
                    },
                    "country": {
                        "type": "string",
                        "description": "内容出品国家名"
                    },
                    "language": {
                        "type": "string",
                        "description": "内容语种"
                    },
                    "is_fee": {
                        "type": "string",
                        "description": "是否收费，\"0\"=免费，\"1\"=收费"
                    }
                }
            },
            "status_code": {
                "type": "number",
                "description": "响应状态码，200=成功，500=出错"
            },
            "error_log": {
                "type": "string",
                "description": "错误信息，仅status_code为500时返回"
            }
        },
        "required": [
            "results",
            "status_code"
        ],
        "usage_hint": "results中各字段反映系统从用户复杂自然语言中解析出的结构化筛选条件；结合status_code判断解析是否成功；当results为空对象时说明系统无法从用户描述中提取有效筛选条件"
    },
    "error_output": {
        "type": "object",
        "properties": {
            "status_code": {
                "type": "number",
                "description": "错误状态码，500表示参数格式错误或服务异常"
            },
            "error_log": {
                "type": "string",
                "description": "错误描述信息，说明具体错误原因"
            }
        }
    },
    "examples": [
        {
            "scenario": "受众描述：适合3到6岁男孩的英语启蒙动画",
            "input": {
                "tag": "英语启蒙",
                "age_range": "3 TO 6",
                "gender": "男",
                "language": "英语"
            },
            "output": {
                "results": {
                    "tag": "英语启蒙",
                    "age_range": "3 TO 6",
                    "gender": "男",
                    "language": "英语"
                },
                "status_code": 200
            }
        },
        {
            "scenario": "问答式查询：有没有免费的中文儿歌（解析为is_fee+language+tag条件）",
            "input": {
                "tag": "儿歌",
                "language": "中文",
                "is_fee": "0"
            },
            "output": {
                "results": {
                    "tag": "儿歌",
                    "language": "中文",
                    "is_fee": "0"
                },
                "status_code": 200
            }
        },
        {
            "scenario": "复杂描述：非国产的、免费的、适合6岁以上孩子的英语教学",
            "input": {
                "tag": "教育",
                "age_range": "6 TO *",
                "language": "英语",
                "is_fee": "0"
            },
            "output": {
                "results": {
                    "tag": "教育",
                    "age_range": "6 TO *",
                    "language": "英语",
                    "is_fee": "0"
                },
                "status_code": 200
            }
        },
        {
            "scenario": "模糊描述：给女童看的日本动漫",
            "input": {
                "tag": "动画",
                "gender": "女",
                "country": "日本"
            },
            "output": {
                "results": {
                    "tag": "动画",
                    "gender": "女",
                    "country": "日本"
                },
                "status_code": 200
            }
        },
        {
            "scenario": "问答式：有没有适合小女孩的免费国产动画",
            "input": {
                "tag": "动画",
                "gender": "女",
                "country": "中国",
                "is_fee": "0"
            },
            "output": {
                "results": {
                    "tag": "动画",
                    "gender": "女",
                    "country": "中国",
                    "is_fee": "0"
                },
                "status_code": 200
            }
        },
        {
            "scenario": "参数格式错误",
            "input": {
                "age_range": "3岁到6岁",
                "gender": "boy",
                "is_fee": "yes"
            },
            "output": {
                "status_code": 500,
                "error_log": "参数格式错误：age_range需为\"N1 TO N2\"/\"* TO N2\"/\"N1 TO *\"模式；gender取值仅支持\"男\"或\"女\"；is_fee取值仅支持\"0\"或\"1\""
            }
        }
    ]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "name": "educ_relate_recommend",
  "description": "基于用户描述的参考媒资进行相似少儿内容推荐，系统将自然语言解析为结构化的参考标题和筛选偏好参数，检索与该参考媒资类型、风格、题材相似的少儿内容。\n适用场景：用户表达了\"基于某内容找类似的\"、\"推荐相关的\"、\"找同类型的\"、\"还有没有像XX这样的\"等相似性推荐意图时使用，如\"我想看类似小猪佩奇的动画片\"、\"推荐和汪汪队差不多的少儿节目\"、\"有没有熊出没那种动画\"。\n不适用场景：用户直接指定明确媒资名称要求播放时不要调用，如\"播放小猪佩奇\"；复杂模糊描述类查询不要调用，如\"有狗狗的动画片\"，应使用educ_search；简单分类浏览请求不要调用，如\"打开少儿频道\"。\n关联工具：复杂语义搜索用educ_search。与educ_search的区别：educ_search用于多维度筛选查询，educ_relate_recommend用于基于已知内容找相似推荐，字段固定为title(参考种子) + content_type/children_second_genre/children_third_genre/training_objectives/role/multiple_intelligences/country/company/language/is_fee/gender/festival/prize 等多维度筛选偏好。\n异常：无法识别参考媒资时返回error_code=REFERENCE_NOT_FOUND；参数格式错误时返回error_code=INVALID_PARAMETER。\n结果使用：title为系统识别的参考媒资，用于检索相似内容,支持空值、单值及多值；其余字段为用户附加的筛选偏好，用于在相似结果中进一步过滤。每个字段支持value(单值精确)/values(多值数组)+operator(or任一匹配/and全部匹配, 默认or)，字段间为隐式AND(同时满足)；is_fee为状态字段，取值0(免费)/1(付费)。",
  "type": "object",
  "properties": {
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND/OR/NOT 组成的复合节点。"
    },
    "sort": {
      "type": "object",
      "description": "排序规则(三种排序键的候选值固定为 asc/desc)，可选 rate(评分)、hot(热度)、new(发布时间) 中的一种或多种组合。三者差异：rate 按 用户/专家评分高低排序，hot 按综合热度(播放量、搜索量等) 排序，new 按发布时间新旧排序。每个排序键的 order 取 asc(正序) 或 desc(倒序)。不传 sort 表示不涉及排序。",
      "properties": {
        "rate": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "hot": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        },
        "new": {
          "type": "object",
          "properties": {
            "order": { "type": "string", "enum": ["asc", "desc"] }
          },
          "required": ["order"]
        }
      },
      "additionalProperties": false,
      "minProperties": 1
    }
  },
  "required": ["query"],
  "additionalProperties": false,

  "definitions": {

    "QueryNode": {
      "description": "查询节点，支持两种形态：1) 布尔复合节点(AND/OR/NOT)；2) 叶子条件节点(单个字段的匹配条件)。",
      "oneOf": [
        { "$ref": "#/definitions/BoolNode" },
        { "$ref": "#/definitions/LeafNode" }
      ]
    },

    "BoolNode": {
      "description": "布尔逻辑组合节点，支持 AND(与)、OR(或)、NOT(非) 三种组合方式。可嵌套组合。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": ["and"],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": { "$ref": "#/definitions/QueryNode" },
              "minItems": 1,
              "description": "OR逻辑：子节点条件中至少满足一个。"
            }
          },
          "required": ["or"],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：对子节点条件取反。"
            }
          },
          "required": ["not"],
          "additionalProperties": false
        }
      ]
    },

    "LeafNode": {
      "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。field 指定维度，value 指定匹配值。",
      "type": "object",
      "oneOf": [
        { "$ref": "#/definitions/ExactFieldCondition" },
        { "$ref": "#/definitions/StatusFieldCondition" },
        { "$ref": "#/definitions/RangeFieldCondition" }
      ]
    },

    "ExactFieldCondition": {
      "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，通过 operator 字段控制维度内的逻辑关系：\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "搜索维度字段名（共16个精确匹配维度）。候选类型分三类：固定候选(取值有限可枚举，模型应在候选内取值或归一化)、半固定候选(常见取值有限但可扩展)、开放型(取值不可枚举，按语义自由填入)。部分字段间存在语义边界，需按各 const 描述中的差异化说明选择正确字段。",
          "oneOf": [
            { "const": "title", "description": "媒资作品标题(开放型)。搜索具体的作品名称时使用。支持空值、单值及多值。与 role(人物角色) 不同——title 是作品本身的名字(如西游记)，role 是作品中的人物(如孙悟空)。典型取值：动画片名(小猪佩奇、汪汪队)、电影名(战狼、流浪地球)、电视剧名(甄嬛传)、游戏名(斗罗大陆、王者荣耀)、儿歌歌曲名(红蜻蜓、葫芦娃)、儿歌集锦名(儿歌多多)、儿童故事名(葫芦娃、三毛)、玩具名(陀螺、溜溜球)、玩具视频名(芭比玩具)、儿童视频名(挖掘机)、漫画名、手工类型、棋类名称、ar百科媒资(摩托车、北极熊)、儿童课程类型(国学经典、启蒙教育)、书本册数(上册、下册)、儿童舞蹈类型-聚好看(萌动)、少儿视频弱标签(老鼠爱大米、起风了)等" },
            { "const": "content_type", "description": "媒资表现形式(固定候选)。仅在用户明确区分媒资形态时使用，候选值：动画、卡通、动画片、动画剧、动画剧集。与 children_third_genre(主题标签) 不同——content_type 描述\"是什么形态的媒资\"，children_third_genre 描述\"讲什么主题的内容\"" },
            { "const": "children_second_genre", "description": "蛛网标签-二级分类(固定候选)。少儿内容蛛网分类体系下的较粗粒度大类标签。与 children_third_genre(三级分类) 是上下位关系——second_genre 是大类，third_genre 是其下的细分标签，候选值：动漫、电影、绘本、儿歌、玩具、真人、音频、宠物、早教、科普、英语、国学、数学、才艺、故事、家长课堂、经典、国学启蒙、数学启蒙、动画电影、漫画、音乐" },
            { "const": "children_third_genre", "description": "蛛网标签-三级分类(固定候选)。少儿内容蛛网分类体系下的较细粒度标签，是 children_second_genre(二级分类) 的下位细分。候选值：搞笑、工程车、红色旋律、交通工具、竞技、机甲、科幻、历史、礼仪品德、励志、美食、魔幻、情绪管理、亲子、奇幻、热血、生活日常、推理、温馨治愈、性格培养、习惯养成、益智动画、友情、动作、感动、冒险、校园、分级阅读、两性教育、入园适应、杂志期刊、综合绘本、益智儿歌、综合儿歌、安静书、巴克球、开箱、史莱姆、食玩、玩具情景剧、玩玩具、儿童真人秀、少儿综艺、真人益智、安全知识、百科综合、动物百科、工程技术、海洋百科、海洋动物、家用电器、节气、节日、科学原理、恐龙、昆虫、鸟类、人体奥秘、人文地理、生活知识、身体健康、细菌病毒、宇宙、植物百科、职业知识、自然现象、词汇、情景教学、小语种、幼小衔接、字母、自然拼读、成语典故、国学启蒙、古诗词、汉字、经典名著、拼音、财商、基础运算、逻辑思维、数学知识、数字、形状、儿童才艺、绘画、口才、乐器、魔术、棋艺、手工、书法、体操、舞蹈、名人故事、神话故事、睡前故事、童话故事、益智故事、幽默、寓言故事、综合故事、分龄早教、家庭教育、亲子游戏、育婴育儿、安全教育、古诗、益智、跳舞、跳舞吧、风舞、舞蹈课、舞、歌舞、跳跳舞、舞蹈健身、舞蹈教程、红色、航天、拼音汉字、拼音汉字、小红军、探案、探险、悬疑、破案、诗、唐诗、文言文、背古诗、宋词、词、诗歌、诗词、诗歌大全、古诗全集、南北朝民歌、诗文、古文、央视" },
            { "const": "training_objectives", "description": "少儿培养目标(固定候选)。按教育目标筛选内容时使用。候选值：宝宝学数字、识字、强健体魄、勇敢、行为认知、乐于助人、生活习惯、认识形状、认识颜色、英语启蒙、认识数字、认识海洋动物、认识动物、认识恐龙、情绪管理、情商培养、手工制作、消防安全、安全教育、拼音、认识时间、安全课教育、诚实守信、兴趣培养、亲子关系、安全教育课程、安全课堂、安全课、安全小知识、爱护动物、安全小课堂、安全教育课、安全课教育课程、培养好性格、认识宇宙、团队协作、财商教育、心理健康、记忆力、朋友交往、安全意识、音乐启蒙、认字、字母学习、学习成语典故、学习古诗词、掌握自然拼读、培养语感、词汇学习、学习经典古文、认识拼音、语言表达能力、了解传统文化、听说能力、学习经典名著、认识日常汉字、阅读能力、了解国外文化、认识食物、了解科学知识、感知世界、认识昆虫、认识各种职业、了解生命科学、了解历史文化、认识球类、认识电器、了解地理知识、观察能力、认识历史、认识气候、日常生活认知、探索能力、认识植物、认识微生物、认识海底世界、了解动物习性、认识蔬菜、认识交通工具、节日认知、环保意识、数学知识、基础运算能力、逻辑思维能力、饮食习惯、情绪情感、讲卫生习惯、自理能力、讲文明讲礼貌、性别教育、爱国精神、培养责任心、积极乐观、树立自信心、独立意识、培养安全感、解决问题能力、社会适应能力、乐于分享、拥有共情能力、人宠关系、正义感、培养幽默感、认识乐器乐理、培养节奏韵律感。与 multiple_intelligences(八大智能) 不同——training_objectives 偏教学目标导向(如培养专注力、启蒙认知)，multiple_intelligences 偏智能维度分类(如语言智能、逻辑数学智能)" },
            { "const": "role", "description": "角色(开放型)。作品中的具体人物角色。与 title(作品名称) 不同——role 是作品中的人物(如孙悟空、路飞)，title 是作品本身的名字(如西游记、海贼王)。适用场景如\"找有路飞出场的动画\"" },
            { "const": "multiple_intelligences", "description": "少儿八大智能(固定候选)。按多元智能理论筛选内容。候选值：人际交往、空间想象、品格习惯、识物认知、数字推理、音乐节奏、肢体运动、语言沟通、学说话。与 training_objectives(培养目标) 不同——multiple_intelligences 是智能维度分类(语言智能、逻辑数学智能、空间智能等)，training_objectives 是教学目标导向" },
            { "const": "country", "description": "国家/地区(开放型)。按地理维度筛选内容时使用。与 language(语言) 不同——country 是地理概念(中国、山东、卢森堡)，language 是语言本身(中文、英语)；当一词多义(如\"中华\")时按用户意图归类。典型取值：外国国家名(卢森堡、苏格兰)、中国国家(中国)、国内省份(山东、陕西)、国内区域名(中华、香港)、国外区域名(中东、欧亚)、地区(中东)等" },
            { "const": "company", "description": "出品公司(开放型)。制作或发行该媒资的公司主体。适用场景如\"找时光传媒出品的动画\"。典型取值：影视出品公司(时光传媒)等" },
            { "const": "language", "description": "语言(固定候选)。影片的主要对白语言、语种或语言版本。与 country(地理) 不同——language 描述作品使用的语言或制作风格的地域版本，country 是地理归属。候选值：英文版、阿拉伯文、阿拉伯语、白俄罗斯语、德文、德语、俄文、俄语、方言、法文、法语、国语、国语版、汉语、库尔德语、孟加拉语、葡萄牙语、普通话、其他语言、日本语、日文、日语、日语版、瑞士德语、泰国语、泰卢固语、泰文、泰语、无对白、西班牙语、西文、英文、英文版、英语、印地语、印度尼西亚语、印度语、印尼语、意大利语、粤语、粤语版、朝鲜语、中国话、中文、中文版、方言版" },
            { "const": "gender", "description": "受众人群性别(固定候选)。按目标受众性别筛选内容时使用。候选值：妇女、美女、男、男版、男宝、男宝宝、男歌手、男声、男生、男声版、男生版、男士、男性、男子、女、女版、女宝、女宝宝、女歌手、女声、女生、女声版、女生版、女士、女式、女性、女子、小男生、小女生、小男孩、女孩、女孩儿、女孩子、小女孩、男孩、男孩儿、男孩子。如果不提及或者男女都可，则置空。适用场景如\"适合男生看的电影\"、\"女生喜欢的动画片\"" },
            { "const": "festival", "description": "节日(固定候选)。按节日筛选内容时使用。后悬置：春节、元宵节、清明节、端午节、七夕节、中秋节、重阳节、腊八节、元旦、国际妇女节、植树节、劳动节、儿童节、建党节、建军节、教师节、国庆节、情人节、愚人节、复活节、母亲节、父亲节、万圣节、感恩节、圣诞节。与 release_year(具体日期范围) 不同——festival 是节日名(除夕、端午)，release_year 是 yyyyMMdd 格式的精确日期区间。" },
            { "const": "prize", "description": "奖项(固定候选)。整体奖项名称。候选值：奥斯卡、奥斯卡奖、奥斯卡金像奖、百花奖、柏林电影节、柏林电影节金熊奖、柏林国际电影节、柏林金熊奖、白玉兰颁奖、白玉兰奖、大众电影百花奖、法国嘎纳电影节、飞天奖、华表奖、华鼎奖、华语电影传媒大奖、戛纳、戛纳电影节、戛纳电影节金棕榈奖、戛纳国际电影节、戛纳金棕榈奖、金鸡百花奖、金鸡百花节、金鸡奖、金鸡节、金马奖、金狮奖、金像奖、金熊奖、金鹰奖、金棕榈、金棕榈奖、上海电视节白玉兰奖、台北金马奖、台湾电影金马奖、威尼斯电影节、威尼斯电影节金狮奖、威尼斯金狮奖、香港电影金像奖、熊猫奖、中国电视金鹰奖、中国电视剧飞天奖、中国电影华表奖、中国电影金鸡奖、凯迪克大奖、中国音乐金钟奖、北京大学生电影节、国际安徒生奖、音乐风云榜、金鹰节。与 sub_prize(子奖项) 是上下位关系——prize 是奖项整体(如金鸡奖、金马奖)，sub_prize 是该奖项下的具体子项(如最佳男配角、最佳女主角)。当用户只说\"金鸡奖\"用 prize，说\"金鸡奖最佳男主角\"则 prize+sub_prize 组合使用" },
            { "const": "sub_prize", "description": "子奖项(开放型)。奖项下的具体子项，是 prize(奖项整体) 的下位细分。与 prize 配合使用以精确指向某一具体奖项子项。典型取值：最佳男配角、最佳女主角、最佳导演等。适用场景如\"找获得最佳男主角的影片\"" },
            { "const": "features", "description": "音效(固定候选)。技术性音效标识。候选值：杜比、杜比音效。适用场景如\"找支持杜比音效的内容\"" },
            { "const": "grade", "description": "年级。按目标受众的学段或筛选内容时使用。候选值：幼儿园阶段(小班、中班、大班)、小学年级(一年级~六年级)等" }
          ]
        },
        "value": { "type": "string", "description": "单值精确匹配" },
        "values": {
          "type": "array",
          "items": { "type": "string" },
          "minItems": 1,
          "description": "多值匹配，逻辑关系由 operator 字段决定"
        },
        "operator": {
          "type": "string",
          "enum": ["and", "or"],
          "default": "or",
          "description": "维度内多值逻辑关系。\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。仅在使用 values 时生效。"
        }
      },
      "required": ["field"],
      "oneOf": [
        { "required": ["value"] },
        { "required": ["values"] }
      ],
      "additionalProperties": false
    },

    "StatusFieldCondition": {
      "description": "状态标识条件(固定候选 0/1)。用于枚举状态字段，值为 0 或 1 的整数。is_fee: 0=免费, 1=付费。不传表示不涉及该条件。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "状态字段名",
          "oneOf": [
            { "const": "is_fee", "description": "免付费标识。0=免费，1=付费。适用场景如\"找免费内容\"、\"找VIP付费内容\"。与 ExactFieldCondition 中的其他维度不同——is_fee 是布尔型状态过滤，不参与主题/属性匹配" }
          ]
        },
        "value": {
          "type": "integer",
          "enum": [0, 1],
          "description": "状态值，0 或 1。is_fee: 0=免费(对应自然语言\"免费/不要钱\")，1=付费(对应自然语言\"付费/VIP\")。自然语言中的\"打折/五折/半价\"等费用相关词需归一化为 0 或 1 后传入。"
        }
      },
      "required": ["field", "value"],
      "additionalProperties": false
    },

    "RangeFieldCondition": {
      "description": "范围匹配条件。支持 age_range(年龄范围) release_year(发布时间范围)含边界。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "范围搜索维度字段名",
          "oneOf": [
            { "const": "age_range", "description": "年龄范围筛选，三种模式：1. \"3 TO 6\"年龄区间；2. \"* TO 6\"不超过6岁；3. \"6 TO *\"不小于6岁" },
            { "const": "release_year", "description": "发布时间范围。from/to 均为 yyyyMMdd 格式字符串，含边界" }
          ]
        },
        "from": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "发布日期下限(含)，age_range为整数，release_year格式 yyyyMMdd，如 20200101。自然语言归一化示例：\"2023年/2023\"→from:20230101；\"去年/上一年/明年\"→from:对应年份1月1日；\"80年代\"→from:19800101；\"近一年/近5年\"等时间段→from:对应起始日期；\"本周一/上周一\"等星期表达→from:对应日期。"
        },
        "to": {
          "type": "string",
          "pattern": "^[0-9]{8}$",
          "description": "发布日期上限(含)，age_range为整数，release_year格式 yyyyMMdd，如 20231231。归一化示例：\"2023年\"→to:20231231；\"80年代\"→to:19891231；\"近一年/近5年\"→to:当天日期；\"本周一/上周一\"→to:对应日期。"
        }
      },
      "required": ["field", "from", "to"],
      "additionalProperties": false
    }
  }
}

{
  "name": "educ_history",
  "title": "少儿历史记录",
  "url": "https://api.example.com/educ/history/query",
  "method": "POST",
  "description": "功能：查询用户的少儿历史观看记录，支持按时间范围（精确到秒）筛选，返回符合条件的历史记录。\n适用场景：用户表达了查看少儿历史记录的意图时使用，如\"我看过的动画\"、\"上周看过什么\"、\"最近一个月的观看记录\"、\"2024年3月给宝宝放过哪些内容\"、\"昨天晚上给宝宝看的动画片\"、\"查一下最近一周的少儿观看记录，但不要上周三的\"。\n不适用场景：1. 用户搜索具体内容时不要调用，应使用educ_slow_search；2. 用户按直达词跳转时不要调用，应使用educ_direct_page；3. 用户要求推荐内容时不要调用；4. 用户查询影视/教育/体育/戏曲/乐活/音乐/K歌等其他业务历史记录时不要调用，应跳转对应业务历史记录页。\n关联工具：搜索具体内容用educ_slow_search，按直达词跳转用educ_direct_page。\n异常：用户无历史记录时返回error_code=NO_HISTORY_RECORD；参数格式错误时返回error_code=INVALID_PARAMETER；细分维度查无时返回error_code=NO_MATCHED_RECORD并提示\"没有找到相关结果，为您展示全部历史记录\"。\n结果使用：time为系统从用户自然语言中解析出的时间范围筛选条件（精确到秒）；根据该条件查询并返回用户的少儿历史观看记录。",
  "parameters": {
    "type": "object",
    "properties": {
      "time": {
        "type": "string",
        "description": "时间范围。指定查询的历史记录时间区间，格式为\"yyyy-MM-dd HH:mm:ss TO yyyy-MM-dd HH:mm:ss\"（精确到秒），如\"2025-03-01 00:00:00 TO 2025-03-31 23:59:59\"表示查询2025年3月1日0点0分0秒至3月31日23点59分59秒的记录。不传时查询全部历史记录。\n支持的时间颗粒度：\n1. 月：本月、上个月、上上个月；\n2. 周：本（这）周、上周、上上周；本周一至本周日；上周一至上周日（以此类推）；\n3. 日：今天、昨天、前天、大前天；上个月的第一天/最后一天；本月的第一天/最后一天；\n4. 早中晚（按时段精确到秒）：凌晨 01:00:00-04:59:59、早上 05:00:00-07:59:59、上午 08:00:00-10:59:59、中午 11:00:00-12:59:59、下午 13:00:00-16:59:59、傍晚 17:00:00-18:59:59、晚上 19:00:00-22:59:59、子夜 23:00:00-次日00:59:59。\n颗粒度可叠加，如\"昨天晚上\"=昨天日期 + 晚上时段（19:00:00-22:59:59）。"
      }
    },
    "required": []
  },

  "output": {
    "type": "object",
    "properties": {
        "time": {
          "type": "string",
          "description": "时间范围解析结果，格式为\"yyyy-MM-dd HH:mm:ss TO yyyy-MM-dd HH:mm:ss\"（精确到秒），未传时为空"
        }
    },
    "usage_hint": "time为系统从用户自然语言中解析出的查询条件（精确到秒），用于筛选历史观看记录；未传的字段表示不做该维度限制。当用户时间表达不属于月/周/日/早中晚任一颗粒度时，应展示全部历史记录并播报\"为您找到全部历史记录\"。"
  },

  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {"type": "string", "description": "错误码，NO_HISTORY_RECORD=用户无历史记录，INVALID_PARAMETER=参数格式错误，NO_MATCHED_RECORD=细分维度查无结果"},
      "error_message": {"type": "string", "description": "错误描述信息"}
    }
  },

  "examples": [
    {
      "scenario": "2024年3月历史（按月）",
      "input": {
        "time": "2024-03-01 00:00:00 TO 2024-03-31 23:59:59"
      },
      "output": {
        "time": "2024-03-01 00:00:00 TO 2024-03-31 23:59:59"
      }
    },
    {
      "scenario": "最近看了什么（不带任何筛选）",
      "input": {},
      "output": {}
    },
    {
      "scenario": "今年看过的（按月范围，精确到秒）",
      "input": {
        "time": "2026-01-01 00:00:00 TO 2026-07-13 23:59:59"
      },
      "output": {
        "time": "2026-01-01 00:00:00 TO 2026-07-13 23:59:59"
      }
    },
    {
      "scenario": "昨天晚上看的（日 + 晚上 19:00:00-22:59:59）",
      "input": {
        "time": "2026-07-12 19:00:00 TO 2026-07-12 22:59:59"
      },
      "output": {
        "time": "2026-07-12 19:00:00 TO 2026-07-12 22:59:59"
      }
    },
    {
      "scenario": "今天上午看的（日 + 上午 08:00:00-10:59:59）",
      "input": {
        "time": "2026-07-13 08:00:00 TO 2026-07-13 10:59:59"
      },
      "output": {
        "time": "2026-07-13 08:00:00 TO 2026-07-13 10:59:59"
      }
    },
    {
      "scenario": "今天凌晨看的（日 + 凌晨 01:00:00-04:59:59）",
      "input": {
        "time": "2026-07-13 01:00:00 TO 2026-07-13 04:59:59"
      },
      "output": {
        "time": "2026-07-13 01:00:00 TO 2026-07-13 04:59:59"
      }
    },
    {
      "scenario": "昨晚子夜看的（跨日 + 子夜 23:00:00-次日00:59:59）",
      "input": {
        "time": "2026-07-12 23:00:00 TO 2026-07-13 00:59:59"
      },
      "output": {
        "time": "2026-07-12 23:00:00 TO 2026-07-13 00:59:59"
      }
    },
    {
      "scenario": "用户无历史记录",
      "input": {},
      "output": {
        "error_code": "NO_HISTORY_RECORD",
        "error_message": "暂无历史观看记录"
      }
    },
    {
      "scenario": "细分维度查无结果（fallback 到全部历史）",
      "input": {
        "time": "2026-07-13 01:00:00 TO 2026-07-13 04:59:59"
      },
      "output": {
        "error_code": "NO_MATCHED_RECORD",
        "error_message": "没有找到相关结果，为您展示全部历史记录"
      }
    }
  ]
}
